    entrada = cache.get(chave)
    if entrada is None:
        if cliente is None:
            api_key = os.environ.get(VARIAVEL_CHAVE)
            if not api_key:
                return None
            cliente = anthropic.Anthropic(api_key=api_key)
        resposta = _perguntar(cliente, lancamento, contas_analiticas, exemplos, cfg)
        if resposta is None:
            return None
